namespace BluewaterHaul;
public sealed class VehicleState {
 public int Id{get;set;}public string Kind{get;set;}="car";public float X{get;set;}public float Z{get;set;}public float Yaw{get;set;}public float Fuel{get;set;}=100;public int Paint{get;set;}public float Damage{get;set;}public bool Destroyed{get;set;}public float BurnTime{get;set;}
 [System.Text.Json.Serialization.JsonIgnore]
 public Vector2 Point{get=>new(X,Z);set{X=value.X;Z=value.Y;}}
}
public record VehicleSpec(string Name,float Width,float Length,float Wheelbase,float Accel,float Brake,float MaxSpeed,float Reverse,float Steer,float Eye) {
 public static VehicleSpec For(string kind)=>kind switch {
  "truck"=>new("Delivery truck",2.5f,10,5.8f,2.8f,6.5f,25,4,.48f,2.65f),
  "pickup"=>new("Pickup",2,5.4f,3.2f,4.4f,8,31,6,.56f,1.65f),
  "van"=>new("Panel van",2,5.8f,3.6f,3.8f,7.5f,28,5,.52f,1.8f),
  "bus"=>new("City bus",2.5f,11,6,2.4f,6,23,3.5f,.45f,2.3f),
  _=>new("Sedan",1.8f,4.6f,2.65f,5.2f,9,35,6,.6f,1.25f)};
}
public static class VehiclePhysics {
 public static Vector2 Forward(float yaw)=>new(-MathF.Sin(yaw),-MathF.Cos(yaw));
 public static float IntegrateSpeed(float speed,float input,bool brake,bool handbrake,bool fueled,float dt,VehicleSpec spec,bool offroad){
  float acceleration=0;if(input>0)acceleration=speed<-.3f?spec.Brake:fueled?spec.Accel:0;else if(input<0)acceleration=speed>.3f?-spec.Brake:fueled?-spec.Accel*.65f:0;
  if(brake||handbrake){float amount=(handbrake?spec.Brake*1.5f:spec.Brake)*dt;speed=Math.Sign(speed)*Math.Max(0,Math.Abs(speed)-amount);}else speed+=acceleration*dt;
  float resistance=(input==0?.22f:.08f)+(offroad?.9f:0);speed*=MathF.Exp(-resistance*dt);return Math.Clamp(speed,-spec.Reverse,offroad?spec.MaxSpeed*.4f:spec.MaxSpeed);
 }
 public static float TurnRate(float speed,float steer,VehicleSpec spec)=>speed/spec.Wheelbase*MathF.Tan(steer)*Math.Clamp(1-Math.Abs(speed)/70,.45f,1);
 public static Vector2[] Outline(Vector2 p,float yaw,VehicleSpec s,float pad=0){var f=Forward(yaw);var r=new Vector2(MathF.Cos(yaw),-MathF.Sin(yaw));float w=s.Width/2+pad,l=s.Length/2+pad;return [p+f*l+r*w,p+f*l-r*w,p-f*l-r*w,p-f*l+r*w];}
 public static bool Overlap(Vector2 a,float ay,VehicleSpec sa,Vector2 b,float by,VehicleSpec sb){var pa=Outline(a,ay,sa);var pb=Outline(b,by,sb);foreach(var axis in new[]{Forward(ay),new Vector2(MathF.Cos(ay),-MathF.Sin(ay)),Forward(by),new Vector2(MathF.Cos(by),-MathF.Sin(by))}){float amin=pa.Min(p=>Vector2.Dot(p,axis)),amax=pa.Max(p=>Vector2.Dot(p,axis));float bmin=pb.Min(p=>Vector2.Dot(p,axis)),bmax=pb.Max(p=>Vector2.Dot(p,axis));if(amax<=bmin||bmax<=amin)return false;}return true;}
}
public static class VehicleModels {
 public static MeshBuilder Make(VehicleState v){var m=new MeshBuilder();var s=VehicleSpec.For(v.Kind);float w=s.Width/2,l=s.Length/2;Color paint=new[]{new Color(166,52,43),new Color(47,97,134),new Color(204,201,182),new Color(69,106,78),new Color(197,163,63),new Color(99,104,120)}[Math.Abs(v.Paint)%6];paint=v.Destroyed?new(49,47,44):Color.Lerp(paint,new Color(79,67,57),Math.Clamp(v.Damage*.006f,0,.6f));Color glass=new(62,113,140),rubber=new(27,31,33),chrome=new(174,182,182);
  void Box(float x0,float y0,float z0,float x1,float y1,float z1,Color c)=>m.Box(new(x0,y0,z0),new(x1,y1,z1),c);
  Box(-w,.4f,-l,w,.95f,l,paint);float wheelZ=s.Wheelbase/2;foreach(float z in new[]{-wheelZ,wheelZ})foreach(int side in new[]{-1,1}){float x=side*(w+.03f);Box(x-.16f,.12f,z-.4f,x+.16f,.83f,z+.4f,rubber);Box(x-.17f,.28f,z-.22f,x+.17f,.65f,z+.22f,chrome);}
  if(v.Kind=="truck"){Box(-w,.9f,-l,w,2.8f,-l+2.5f,paint);Box(-w*.86f,1.65f,-l-.02f,w*.86f,2.5f,-l+.01f,glass);Box(-w*.98f,1.65f,-l+.4f,w*.98f,2.45f,-l+2.1f,glass);Box(-w,1,-l+2.7f,w,3.25f,l,new(205,200,177));Box(-w+.1f,1.1f,l,w-.1f,3.05f,l+.03f,new(162,171,171));Box(-.035f,1.1f,l+.04f,.035f,3.05f,l+.08f,chrome);}
  else if(v.Kind=="bus"){Box(-w,.95f,-l,w,3.1f,l,new(223,217,193));Box(-w+.02f,1.1f,-l-.03f,w-.02f,2.8f,-l+.02f,glass);for(float z=-l+.6f;z<l-.7f;z+=1.3f){Box(-w-.015f,1.8f,z,-w+.015f,2.75f,z+1,glass);Box(w-.015f,1.8f,z,w+.015f,2.75f,z+1,glass);}Box(-w-.025f,1.15f,-l+.4f,w+.025f,1.5f,l-.4f,paint);Box(w, .5f,-l+.4f,w+.04f,2.7f,-l+1.5f,new(74,101,115));}
  else if(v.Kind=="van"){Box(-w,.9f,-l+1,w,2.55f,l,paint);Box(-w*.9f,1.25f,-l+.96f,w*.9f,2.3f,-l+1.02f,glass);Box(-w-.015f,1.35f,-l+1.1f,w+.015f,2.15f,-l+2,glass);Box(-w*.8f,1.2f,l,w*.8f,2.2f,l+.02f,new(148,157,161));}
  else {float rear=v.Kind=="pickup"?-.1f:1.2f;Box(-w*.88f,.95f,-1.2f,w*.88f,1.75f,rear,paint);Box(-w*.82f,1.05f,-1.23f,w*.82f,1.65f,-1.19f,glass);Box(-w*.9f,1.05f,-1.1f,-w*.87f,1.65f,rear-.1f,glass);Box(w*.87f,1.05f,-1.1f,w*.9f,1.65f,rear-.1f,glass);if(v.Kind=="pickup"){Box(-w,.95f,.1f,-w+.12f,1.4f,l,paint);Box(w-.12f,.95f,.1f,w,1.4f,l,paint);Box(-w,1.1f,l-.15f,w,1.4f,l,paint);Box(-w+.13f,.96f,.2f,w-.13f,1,l-.16f,new(58,61,61));}else Box(-w*.82f,1.05f,rear-.01f,w*.82f,1.65f,rear+.02f,glass);}
  Box(-w,.42f,-l-.08f,w,.59f,-l,chrome);Box(-w,.42f,l,w,.59f,l+.08f,chrome);foreach(int side in new[]{-1,1}){float x=side*(w-.25f);Box(x-.16f,.68f,-l-.1f,x+.16f,.87f,-l-.08f,new(244,235,176));Box(x-.16f,.67f,l+.08f,x+.16f,.86f,l+.1f,new(201,45,37));}if(v.Damage>0)Box(-w*.7f,.96f,-l+.1f,w*.7f,1.01f,-l+.55f,new(64,57,50));return m;
 }
}
public sealed partial class SarniaGame {
 List<VehicleState> fleet=[];int activeVehicle;bool thirdPerson=true;float steering,cameraDistance=10;Vector3 cameraEye;bool cameraReady;float fleetNotice;
 VehicleState ActiveVehicle=>fleet.First(v=>v.Id==activeVehicle);
 VehicleSpec ActiveSpec=>VehicleSpec.For(ActiveVehicle.Kind);
 float ActiveFuel=>fleet.Count==0?state.Fuel:activeVehicle==0?state.Fuel:ActiveVehicle.Fuel;
 void InitializeVehicles(){fleet=[new(){Id=0,Kind="truck",Point=truck,Yaw=state.TruckYaw,Paint=0,Fuel=state.Fuel}];activeVehicle=0;int id=1;var bays=world.Areas.Where(a=>a.Kind=="parking").OrderBy(a=>Vector2.DistanceSquared(Geo.V(a.Points[0]),truck)).ToList();
  foreach(var area in bays){if(id>85)break;float x0=area.Points.Min(p=>p[0]),x1=area.Points.Max(p=>p[0]),z0=area.Points.Min(p=>p[1]),z1=area.Points.Max(p=>p[1]);var center=new Vector2((x0+x1)/2,(z0+z1)/2);if(center.X< -5400||center.Y< -3000)continue;string kind=new[]{"car","pickup","van","bus"}[(id-1)%4];float heading=0;var candidate=new VehicleState{Id=id,Kind=kind,Point=center,Yaw=heading,Paint=id};if(!VehicleBlocked(candidate.Point,heading,candidate.Id,VehicleSpec.For(kind))&&VehiclePhysics.Outline(center,heading,VehicleSpec.For(kind)).All(p=>Geo.Contains(area.Points,p))){fleet.Add(candidate);id++;}}
  // Deterministic parked fleet placed only inside mapped parking surfaces.
  state.Vehicles=fleet;cameraReady=false;
 }
 void SynchronizeTruck(){var v=fleet.FirstOrDefault(v=>v.Id==0);if(v!=null){v.Point=truck;v.Yaw=state.TruckYaw;v.Fuel=state.Fuel;}}
 void RestoreVehicles(){if(state.Vehicles.Count==0)InitializeVehicles();else fleet=state.Vehicles.Where(v=>v.Id>=0&&v.Kind is "truck" or "car" or "pickup" or "van" or "bus").DistinctBy(v=>v.Id).ToList();if(!fleet.Any(v=>v.Id==0))fleet.Insert(0,new(){Id=0,Kind="truck",Point=truck,Yaw=state.TruckYaw,Fuel=state.Fuel});activeVehicle=fleet.Any(v=>v.Id==state.ActiveVehicle)?state.ActiveVehicle:0;thirdPerson=state.ThirdPerson;SynchronizeTruck();if(driving){ActiveVehicle.Point=position;ActiveVehicle.Yaw=yaw;}steering=0;cameraReady=false;walkingVelocity=Vector2.Zero;}
 bool VehicleBlocked(Vector2 p,float heading,int ignore,VehicleSpec spec){var points=VehiclePhysics.Outline(p,heading,spec,.15f);if(points.Any(Blocked))return true;var f=VehiclePhysics.Forward(heading);var r=new Vector2(MathF.Cos(heading),-MathF.Sin(heading));for(float z=-spec.Length/2;z<=spec.Length/2;z+=.8f)for(int side=-1;side<=1;side++)if(Blocked(p+f*z+r*(spec.Width/2+.15f)*side))return true;
  foreach(var other in fleet){if(other.Id==ignore||Vector2.DistanceSquared(p,other.Point)>400)continue;if(VehiclePhysics.Overlap(p,heading,spec,other.Point,other.Yaw,VehicleSpec.For(other.Kind)))return true;}return ignore>=0&&(TrafficBlocked(p,heading,spec)||CitizenBlocked(p,heading,spec)||PoliceBlocked(p,heading));}
 bool PedestrianVehicleBlocked(Vector2 p)=>interior==0&&(TrafficNear(p)||fleet.Any(v=>VehiclePhysics.Outline(v.Point,v.Yaw,VehicleSpec.For(v.Kind),.3f) is var corners&&Geo.Contains(corners.Select(c=>new[]{c.X,c.Y}).ToList(),p)));
 VehicleState? NearVehicle()=>fleet.Where(v=>Vector2.DistanceSquared(position,v.Point)<MathF.Pow(VehicleSpec.For(v.Kind).Length/2+3,2)).OrderBy(v=>Vector2.DistanceSquared(position,v.Point)).FirstOrDefault();
 bool ExitVehicle(){if(Math.Abs(speed)>.6f){Tell("Stop before leaving the vehicle.");return false;}var v=ActiveVehicle;v.Point=position;v.Yaw=yaw;if(v.Id==0){truck=position;state.TruckYaw=yaw;}var spec=ActiveSpec;var f=VehiclePhysics.Forward(yaw);var r=new Vector2(MathF.Cos(yaw),-MathF.Sin(yaw));foreach(float side in new[]{1f,-1f})for(int i=0;i<3;i++){var q=position+r*side*(spec.Width/2+1)+f*(-spec.Length*.2f+i*1.5f);if(Blocked(q)||PedestrianVehicleBlocked(q))continue;driving=false;position=q;speed=0;cabLook=0;pitch=0;cameraReady=false;Tell(spec.Name+" parked. E enters a nearby vehicle.");return true;}Tell("No safe exit beside the vehicle. Move away from the wall.");return false;}
 void EnterVehicle(VehicleState v){if(v.Destroyed){Tell("This vehicle is a wreck. Bring it to a repair stop with H, then K.");return;}walkingVelocity=Vector2.Zero;VehicleTheft(v);activeVehicle=v.Id;position=v.Point;yaw=v.Yaw;driving=true;speed=steering=cabLook=pitch=0;cameraReady=false;Tell("Driving "+VehicleSpec.For(v.Kind).Name+" / V camera / SPACE brake");}
 void DriveVehicle(KeyboardState keys,float dt){var v=ActiveVehicle;if(v.Destroyed){speed=0;ExitVehicle();return;}var spec=ActiveSpec;float input=(keys.IsKeyDown(Keys.W)?1:0)-(keys.IsKeyDown(Keys.S)?1:0);float desired=((keys.IsKeyDown(Keys.A)?1:0)-(keys.IsKeyDown(Keys.D)?1:0))*spec.Steer/(1+Math.Abs(speed)*.07f);steering=MathHelper.Lerp(steering,desired,1-MathF.Exp(-dt*6));bool road=carRouter.Snap(position) is var snap&&Vector2.DistanceSquared(snap.Point,position)<100;speed=VehiclePhysics.IntegrateSpeed(speed,input,keys.IsKeyDown(Keys.Space),keys.IsKeyDown(Keys.LeftShift),ActiveFuel>0,dt,spec,!road);
  speed*=MathF.Exp(-dt*v.Damage*.006f);
  int steps=Math.Max(1,(int)MathF.Ceiling(Math.Abs(speed)*dt/.35f));for(int i=0;i<steps;i++){float step=dt/steps;float nextYaw=yaw+VehiclePhysics.TurnRate(speed,steering,spec)*step;var q=position+VehiclePhysics.Forward((yaw+nextYaw)/2)*speed*step;if(VehicleBlocked(q,nextYaw,v.Id,spec)){speed=ResolveCrash(q,nextYaw,speed);steering*=.5f;if(fleetNotice<=0){Tell("Contact: brake, reverse, or steer clear.");fleetNotice=2;}break;}position=q;yaw=nextYaw;}v.Point=position;v.Yaw=yaw;float fuel=Math.Max(0,ActiveFuel-Math.Abs(speed)*dt*(v.Kind is "truck" or "bus"?.00065f:.00035f));v.Fuel=fuel;if(v.Id==0){truck=position;state.TruckYaw=yaw;state.Fuel=fuel;}fleetNotice-=dt;
 }
 void DrawVehicles(MeshBuilder m){SynchronizeTruck();foreach(var v in fleet){if(driving&&v.Id==activeVehicle&&!thirdPerson)continue;if(Vector2.DistanceSquared(v.Point,position)>550*550)continue;var model=VehicleModels.Make(v);var matrix=Matrix.CreateScale(1,v.Destroyed?.55f:1,1)*Matrix.CreateRotationY(v.Yaw)*Matrix.CreateTranslation(v.X,GroundHeight(v.Point),v.Z);foreach(var vertex in model.Vertices)m.Vertices.Add(new(Vector3.Transform(vertex.Position,matrix),vertex.Color));}}
 void ApplyVehicleCamera(ref Vector3 eye,ref Vector3 forward){if(interior!=0||!thirdPerson){cameraReady=false;return;}float angle=yaw+(driving?cabLook:0);var focus=Geo.V3(position,GroundHeight(position)+(driving?1.3f:1.2f));var behind=new Vector3(MathF.Sin(angle),0,MathF.Cos(angle));if(!driving)focus+=new Vector3(MathF.Cos(angle)*.45f,0,-MathF.Sin(angle)*.45f);float distance=driving?Math.Max(cameraDistance,ActiveSpec.Length*.85f):Math.Clamp(cameraDistance*.6f,3,10);var wanted=focus+behind*distance+new Vector3(0,driving?3.8f:2.2f,0);wanted.Y+=MathF.Sin(-pitch)*distance*.4f;
  for(int i=1;i<=24;i++){var q=Vector3.Lerp(focus,wanted,i/24f);if(CameraOccluded(q)){wanted=Vector3.Lerp(focus,wanted,Math.Max(.1f,(i-2)/24f));break;}}
  if(!cameraReady){cameraEye=wanted;cameraReady=true;}else cameraEye=Vector3.Lerp(cameraEye,wanted,1-MathF.Exp(-frameDt*12));for(int i=1;i<=24;i++)if(CameraOccluded(Vector3.Lerp(focus,cameraEye,i/24f))){cameraEye=wanted;break;}eye=cameraEye;forward=focus-eye;if(forward.LengthSquared()<.01f)forward=Vector3.Forward;forward.Normalize();}
 bool CameraOccluded(Vector3 p){var v=new Vector2(p.X,p.Z);if(p.Y<GroundHeight(v)+.3f)return true;if(buildingGrid.TryGetValue(((int)MathF.Floor(v.X/128),(int)MathF.Floor(v.Y/128)),out var bs))return bs.Any(b=>p.Y<b.Height+1&&Geo.Contains(b.Points,v));return false;}
 void DrawAvatar(MeshBuilder m){if(driving||interior!=0||!thirdPerson)return;var body=new MeshBuilder();body.Box(new(-.22f,.65f,-.16f),new(.22f,1.35f,.16f),new(136,53,41));body.Box(new(-.16f,1.35f,-.16f),new(.16f,1.7f,.16f),new(208,166,128));float swing=walkingVelocity.LengthSquared()>.01f?MathF.Sin(walkPhase)*.15f:0;foreach(float side in new[]{-1f,1f}){body.Box(new(side*.13f-.08f,0,side*swing-.09f),new(side*.13f+.08f,.65f,side*swing+.09f),new(47,73,98));body.Box(new(side*.3f-.06f,.72f,-side*swing-.07f),new(side*.3f+.06f,1.25f,-side*swing+.07f),new(136,53,41));}var matrix=Matrix.CreateRotationY(avatarYaw)*Matrix.CreateTranslation(position.X,GroundHeight(position),position.Y);foreach(var v in body.Vertices)m.Vertices.Add(new(Vector3.Transform(v.Position,matrix),v.Color));}

 void SaveVehicles(){SynchronizeTruck();if(driving){ActiveVehicle.Point=position;ActiveVehicle.Yaw=yaw;}state.Vehicles=fleet;state.ActiveVehicle=activeVehicle;state.ThirdPerson=thirdPerson;}
 void RecoverVehicle(){if(Trouble.Heat>0){Tell("Recovery unavailable during a police search.");return;}if(!driving&&NearVehicle() is {} wreck&&wreck.Destroyed){var station=world.Pois.Where(p=>p.Kind is "fuel" or "car_repair").MinBy(p=>Vector2.DistanceSquared(Geo.V(p.Point),wreck.Point));if(station!=null){wreck.Point=FindRoad(Geo.V(station.Point));position=SidewalkPoint(wreck.Point);if(wreck.Id==0)truck=wreck.Point;Tell("Wreck towed to repair stop. K repairs it.");}return;}if(Trouble.Heat>0){Tell("Recovery unavailable during a police search.");return;}if(!driving){EnterVehicle(fleet.First(v=>v.Id==0));}var v=ActiveVehicle;var p=FindRoad(position);for(int i=0;i<12;i++){var q=FindRoad(p+new Vector2(i*8,0));if(!VehicleBlocked(q,yaw,v.Id,ActiveSpec)){position=q;v.Point=q;speed=0;cameraReady=false;if(v.Id==0)truck=q;Tell("Recovered "+ActiveSpec.Name+" to road.");return;}}Tell("No clear recovery position nearby.");}
 void VehicleSmoke(){
  SynchronizeTruck();if(fleet.Select(v=>v.Kind).Distinct().Count()<5)throw new InvalidDataException("Fleet lacks a vehicle class");
  foreach(var kind in new[]{"car","pickup","van","bus"}){var v=fleet.First(v=>v.Kind==kind);position=v.Point+new Vector2(VehicleSpec.For(kind).Width/2+1.4f,0);driving=false;Interact();if(!driving||activeVehicle!=v.Id)throw new InvalidDataException("Vehicle entry failed: "+kind);var parked=position;for(int frame=0;frame<30;frame++)DriveVehicle(new KeyboardState(Keys.W),1f/60);if(Vector2.Distance(parked,position)<.1f)throw new InvalidDataException("Vehicle did not drive: "+kind);for(int frame=0;frame<60;frame++)DriveVehicle(new KeyboardState(Keys.Space),1f/60);if(speed!=0)throw new InvalidDataException("Vehicle did not stop: "+kind);thirdPerson=true;cameraReady=false;Capture("vehicle-"+kind);if(!ExitVehicle())throw new InvalidDataException("Vehicle exit failed: "+kind);}
  var selected=fleet.First(v=>v.Kind=="pickup");EnterVehicle(selected);selected.Fuel=42;thirdPerson=false;Save();int id=selected.Id;fleet=[];LoadSave();if(activeVehicle!=id||!driving||ActiveVehicle.Fuel!=42||thirdPerson)throw new InvalidDataException("Fleet/camera save failed");thirdPerson=true;cameraReady=false;Capture("pickup-chase");ExitVehicle();Console.WriteLine($"PASS vehicles: {fleet.Count} vehicles; all classes entered/exited; active vehicle, fuel, parking and camera persisted.");
 }
